DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.live_followup_admin_summary(uuid)'::regprocedure) INTO def;def:=replace(def,'ORDER BY date DESC','ORDER BY start_date DESC');EXECUTE def; END $$;
CREATE OR REPLACE FUNCTION public.live_followup_policy_simulate() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE ev uuid:=gen_random_uuid(); nid uuid:=gen_random_uuid(); igid uuid; job uuid:=gen_random_uuid(); user_id uuid:=auth.uid(); result jsonb:='{}'; ctx jsonb; cid text:='simulation-comment-'||gen_random_uuid(); uname text:='simulation_'||replace(gen_random_uuid()::text,'-',''); wa text:='5533999999988'; lid text:='999999999999999999';
BEGIN IF NOT has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
 SELECT id INTO igid FROM whatsapp_numbers WHERE provider='instagram' AND is_active LIMIT 1;
 BEGIN
 INSERT INTO events(id,name,live_followup_enabled,wa_initial_number_id,is_live_broadcasting,live_active_until) VALUES(ev,'SIMULATED POLICY',true,nid,true,now()+interval '1 hour');
 result:=result||jsonb_build_object('sender_initial',live_event_sender(ev)->>'id'=nid::text);
 UPDATE events SET wa_initial_number_id=NULL,whatsapp_number_id=nid WHERE id=ev;
 result:=result||jsonb_build_object('sender_fallback',live_event_sender(ev)->>'id'=nid::text);
 UPDATE events SET whatsapp_number_id=NULL WHERE id=ev;
 result:=result||jsonb_build_object('sender_missing',live_event_sender(ev)->>'id' IS NULL);
 INSERT INTO live_comments(event_id,comment_id,username,source_pc,created_at) VALUES(ev,cid,uname,'meta-webhook-live',now());
 INSERT INTO instagram_user_links(username,ig_user_id) VALUES(uname,'simulation-user-'||uname);
 INSERT INTO whatsapp_messages(phone,whatsapp_number_id,message_id,message,direction,channel,created_at) VALUES('simulation-user-'||uname,igid,cid,'💬 Comentário no Live: quero','incoming','instagram',now());
 ctx:=instagram_reply_context(uname,ev,igid); result:=result||jsonb_build_object('comment_not_dm_window',NOT (ctx->>'window_open')::boolean,'live_private_allowed',ctx->'comment_ids' ? cid);
 UPDATE events SET live_active_until=now()-interval '1 second' WHERE id=ev;
 ctx:=instagram_reply_context(uname,ev,igid);result:=result||jsonb_build_object('ended_live_blocked',NOT (ctx->'comment_ids' ? cid));
 UPDATE live_comments SET source_pc='meta-webhook',created_at=now()-interval '6 days' WHERE comment_id=cid;
 ctx:=instagram_reply_context(uname,ev,igid);result:=result||jsonb_build_object('post_within_7_days',ctx->'comment_ids' ? cid);
 UPDATE live_comments SET created_at=now()-interval '7 days 1 second' WHERE comment_id=cid;
 ctx:=instagram_reply_context(uname,ev,igid);result:=result||jsonb_build_object('post_after_7_days_blocked',NOT (ctx->'comment_ids' ? cid));
 INSERT INTO whatsapp_messages(phone,whatsapp_number_id,message,direction,channel,created_at) VALUES('simulation-user-'||uname,igid,'Oi','incoming','instagram',now()-interval '23 hours');
 ctx:=instagram_reply_context(uname,ev,igid);result:=result||jsonb_build_object('dm_opens_24h',(ctx->>'window_open')::boolean);
 UPDATE whatsapp_messages SET created_at=now()-interval '24 hours 1 second' WHERE phone='simulation-user-'||uname AND message='Oi';
 ctx:=instagram_reply_context(uname,ev,igid);result:=result||jsonb_build_object('dm_after_24h_closed',NOT (ctx->>'window_open')::boolean);
 INSERT INTO whatsapp_lid_phone_map(whatsapp_number_id,lid,phone_key) VALUES(igid,lid,automation_phone_key(wa));
 INSERT INTO live_followup_jobs(id,event_id,customer_key,phone,whatsapp_number_id,channel,type,step,sequence_key,scheduled_at,base_at) VALUES(job,ev,'simulation',wa,igid,'whatsapp','D',0,'simulation-'||ev,now(),now()-interval '1 hour');
 INSERT INTO whatsapp_messages(phone,whatsapp_number_id,message,direction,is_group,created_at) VALUES(lid,igid,'parar','incoming',false,now());
 ctx:=live_followup_job_context(job);result:=result||jsonb_build_object('lid_reply_stops',(ctx->>'customer_replied')::boolean,'lid_optout_stops',(ctx->>'opted_out')::boolean);
 INSERT INTO whatsapp_messages(phone,whatsapp_number_id,message,direction,sender_user_id,created_at) VALUES(lid,igid,'atendendo','outgoing',user_id,now());
 ctx:=live_followup_job_context(job);result:=result||jsonb_build_object('lid_manual_stops',(ctx->>'manual_recent')::boolean);
 result:=result||jsonb_build_object('other_instance_no_alias',NOT (lid=ANY(live_followup_contact_aliases(wa,nid,NULL))));
 RAISE EXCEPTION USING ERRCODE='P9002',MESSAGE='rollback isolated policy';
 EXCEPTION WHEN SQLSTATE 'P9002' THEN NULL; END;
 RETURN result||jsonb_build_object('provider_calls',0,'rolled_back',true);
END $$;
REVOKE ALL ON FUNCTION public.live_followup_policy_simulate() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.live_followup_policy_simulate() TO authenticated;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.instagram_reply_context(text,uuid,uuid)'::regprocedure) INTO def;def:=replace(def,'''meta-webhook-live'',''meta-live-media-sync''','''meta-webhook-live'',''meta-live-media-sync'',''meta-live-media-sync'''); EXECUTE def; END $$;